WITH recent_departments AS (SELECT * FROM departments WHERE location IN ('Chiang Mai', 'Singapore')), agg AS (SELECT CASE WHEN budget >= 4125000 THEN 'high' WHEN budget >= 1889000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(CASE WHEN location = 'Chiang Mai' THEN budget ELSE 0 END) AS chiang_mai_budget, AVG(budget) AS avg_budget FROM recent_departments GROUP BY CASE WHEN budget >= 4125000 THEN 'high' WHEN budget >= 1889000 THEN 'mid' ELSE 'low' END) SELECT budget_bucket, chiang_mai_budget, avg_budget FROM agg WHERE avg_budget < 1834000 ORDER BY 1 LIMIT 10;
